from __future__ import annotations

import json
import re
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATASET = Path("/app/dataset")
UTC_START = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
UTC_END = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")


def _load_calibration() -> dict:
    with open(DATASET / "sensors_calibration.json") as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def _read_production_csv(farm_id: str) -> pd.DataFrame:
    path = DATASET / f"production_{farm_id}.csv"
    raw = path.read_bytes()
    encoding = "utf-16" if raw.startswith(b"\xff\xfe") else "utf-8"

    with open(path, encoding=encoding) as f:
        for _ in range(3):
            next(f)
        header = next(f)

    sep = ";" if header.count(";") > header.count(",") else ","
    kwargs = {
        "encoding": encoding,
        "engine": "python",
        "sep": sep,
        "skiprows": 3,
    }
    if sep == ";":
        kwargs.update({"decimal": ",", "thousands": "."})

    return pd.read_csv(path, **kwargs)


def _parse_timestamp(value) -> pd.Timestamp:
    if pd.isna(value):
        return pd.NaT

    text = str(value).strip()
    formats = (
        ("%Y-%m-%d %H:%M:%S", r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$"),
        ("%d.%m.%Y %H:%M:%S", r"^\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}$"),
    )
    for fmt, pattern in formats:
        if re.match(pattern, text):
            try:
                return pd.Timestamp(pd.to_datetime(text, format=fmt))
            except (TypeError, ValueError):
                return pd.NaT

    return pd.NaT


def _unit_factor_to_kwh(unit: str) -> float:
    unit = unit.lower()
    if unit == "kwh":
        return 1.0
    if unit == "mwh":
        return 1000.0
    if unit == "wh":
        return 0.001
    if unit == "btu":
        return 0.0002930710701722222
    if unit == "kw":
        return 1.0
    raise ValueError(f"Unsupported unit: {unit}")


def _registry() -> pd.DataFrame:
    farms = pd.read_csv(DATASET / "farms.csv")
    registry = pd.read_csv(DATASET / "farm_registry.csv")

    farms["farm_name_key"] = farms["farm_name"].str.strip().str.lower()
    registry["farm_name_key"] = registry["farm_name"].str.strip().str.lower()

    return registry.merge(
        farms[["farm_name_key", "timezone"]],
        on="farm_name_key",
        how="left",
    )


def _completed_maintenance_windows(farm_id: str, timezone: str) -> list[tuple[pd.Timestamp, pd.Timestamp]]:
    local_tz = ZoneInfo(timezone)
    windows = []

    if farm_id == "FARM_C":
        windows.append(("2024-03-16 08:00:00", "2024-03-16 12:00:00"))
    elif farm_id == "FARM_F":
        windows.append(("2024-03-15 12:00:00", "2024-03-15 14:00:00"))

    return [
        (
            pd.Timestamp(start).tz_localize(local_tz).tz_convert("UTC"),
            pd.Timestamp(end).tz_localize(local_tz).tz_convert("UTC"),
        )
        for start, end in windows
    ]


def _nominal_interval_hours(timestamps: pd.Series) -> float:
    diffs = timestamps.sort_values().drop_duplicates().diff().dropna()
    diffs = diffs[diffs > pd.Timedelta(0)]
    if diffs.empty:
        return 0.0
    return float(diffs.median() / pd.Timedelta(hours=1))


def answer() -> dict[str, int]:
    calibration = _load_calibration()
    totals: dict[str, int] = {}

    for row in _registry().itertuples(index=False):
        farm_id = row.farm_id
        timezone = row.timezone

        if farm_id not in calibration:
            totals[farm_id] = 0
            continue

        config = calibration[farm_id]
        value_column = config["calibration_data"]["value_column_name"]
        offset = float(config["calibration_data"]["calibration_offset"])
        reading_type = config["sensor_info"]["reading_type"].lower()
        unit_factor = _unit_factor_to_kwh(config["sensor_info"]["unit"])

        df = _read_production_csv(farm_id)
        timestamp_column = next(col for col in df.columns if col.strip() == "timestamp")

        df = df.drop_duplicates()
        df = df.drop_duplicates(subset=[timestamp_column], keep="last")
        df["local_timestamp"] = df[timestamp_column].map(_parse_timestamp)
        df = df.dropna(subset=["local_timestamp"]).copy()

        if df.empty:
            totals[farm_id] = 0
            continue

        interval_hours = _nominal_interval_hours(df["local_timestamp"])
        utc_timestamps = (
            pd.DatetimeIndex(df["local_timestamp"])
            .tz_localize(ZoneInfo(timezone), ambiguous="NaT", nonexistent="NaT")
            .tz_convert("UTC")
        )
        df["timestamp_utc"] = utc_timestamps
        df = df.dropna(subset=["timestamp_utc"])

        df = df[(df["timestamp_utc"] >= UTC_START) & (df["timestamp_utc"] < UTC_END)].copy()

        for start, end in _completed_maintenance_windows(farm_id, timezone):
            df = df[~((df["timestamp_utc"] >= start) & (df["timestamp_utc"] < end))]

        reading = pd.to_numeric(df[value_column], errors="coerce") - offset
        reading = reading.dropna()
        reading = reading[reading >= 0]

        if reading_type == "energy":
            total_kwh = float((reading * unit_factor).sum())
        elif reading_type == "power":
            total_kwh = float((reading * unit_factor * interval_hours).sum())
        else:
            total_kwh = 0.0

        totals[farm_id] = round(total_kwh)

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
